// Install: carbon-components-react@7.48.0 + carbon-components
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import {
  DataTable,
  Table,
  TableHead,
  TableRow,
  TableHeader,
  TableBody,
  TableCell,
} from 'carbon-components-react';

const rows = [
  { id: 'a', name: 'Load balancer 1', status: 'Disabled' },
  { id: 'b', name: 'Load balancer 2', status: 'Active' },
];

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'status', header: 'Status' },
];

function App() {
  return (
    <DataTable rows={rows} headers={headers} isSortable>
      {({ rows, headers, getTableProps, getHeaderProps, getRowProps }) => (
        <Table {...getTableProps()} size="compact">
          <TableHead>
            <TableRow>
              {headers.map(header => (
                <TableHeader
                  key={header.key}
                  // force this column to be sortable
                  {...getHeaderProps({
                    header,
                    isSortable: true,
                    // an arbitrary prop to pass down, e.g. `id`
                    id: `th-${header.key}`,
                    'data-test': `th-${header.key}`,
                  })}
                >
                  {header.header}
                </TableHeader>
              ))}
            </TableRow>
          </TableHead>
          <TableBody>
            {rows.map(row => (
              <TableRow key={row.id} {...getRowProps({ row })}>
                {row.cells.map(cell => (
                  <TableCell key={cell.id}>{cell.value}</TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      )}
    </DataTable>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));

/*
  After you run this, inspect the DOM:
  - The <th> elements for sortable columns will NOT have the id="th-name" or data-test="th-name"
  - Instead, those attributes live on the inner <button> tag.
